```turtle
@prefix fis: <http://example.org/onto/securities#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities>
    a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology"@en ;
    rdfs:comment "An ontology formalizing financial instruments, securities, derivatives, equities, and debts based strictly on domain corpus descriptions. Conflicts regarding the legal scope of 'security' across jurisdictions are documented."@en .

#################################################################
#    Annotation Properties
#################################################################

rdfs:label a owl:AnnotationProperty .
rdfs:comment a owl:AnnotationProperty .

#################################################################
#    Object Properties
#################################################################

fis:hasIssuer
    a owl:ObjectProperty ;
    rdfs:label "has issuer"@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:LegalEntity ;
    owl:inverseOf fis:isIssuerOf .

fis:isIssuerOf
    a owl:ObjectProperty ;
    rdfs:label "is issuer of"@en ;
    rdfs:domain fis:LegalEntity ;
    rdfs:range fis:FinancialInstrument .

fis:hasHolder
    a owl:ObjectProperty ;
    rdfs:label "has holder"@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:LegalEntity ;
    owl:inverseOf fis:isHolderOf .

fis:isHolderOf
    a owl:ObjectProperty ;
    rdfs:label "is holder of"@en ;
    rdfs:domain fis:LegalEntity ;
    rdfs:range fis:FinancialInstrument .

fis:hasUnderlying
    a owl:ObjectProperty ;
    rdfs:label "has underlying"@en ;
    rdfs:domain fis:Derivative ;
    rdfs:range owl:Thing ;
    owl:inverseOf fis:isUnderlyingOf .

fis:isUnderlyingOf
    a owl:ObjectProperty ;
    rdfs:label "is underlying of"@en ;
    rdfs:domain owl:Thing ;
    rdfs:range fis:Derivative .

fis:hasCollateral
    a owl:ObjectProperty ;
    rdfs:label "has collateral"@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range owl:Thing ;
    owl:inverseOf fis:isCollateralOf .

fis:isCollateralOf
    a owl:ObjectProperty ;
    rdfs:label "is collateral of"@en ;
    rdfs:domain owl:Thing ;
    rdfs:range fis:DebtSecurity .

fis:hasReferenceEntity
    a owl:ObjectProperty ;
    rdfs:label "has reference entity"@en ;
    rdfs:domain fis:CreditDefaultSwap ;
    rdfs:range fis:LegalEntity ;
    owl:inverseOf fis:isReferenceEntityOf .

fis:isReferenceEntityOf
    a owl:ObjectProperty ;
    rdfs:label "is reference entity of"@en ;
    rdfs:domain fis:LegalEntity ;
    rdfs:range fis:CreditDefaultSwap .

fis:hasExchange
    a owl:ObjectProperty ;
    rdfs:label "has exchange"@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:StockExchange ;
    owl:inverseOf fis:isExchangeOf .

fis:isExchangeOf
    a owl:ObjectProperty ;
    rdfs:label "is exchange of"@en ;
    rdfs:domain fis:StockExchange ;
    rdfs:range fis:FinancialInstrument .

fis:hasPortfolioSecurity
    a owl:ObjectProperty ;
    rdfs:label "has portfolio security"@en ;
    rdfs:domain fis:InvestmentFund ;
    rdfs:range fis:Security ;
    owl:inverseOf fis:isPortfolioSecurityOf .

fis:isPortfolioSecurityOf
    a owl:ObjectProperty ;
    rdfs:label "is portfolio security of"@en ;
    rdfs:domain fis:Security ;
    rdfs:range fis:InvestmentFund .

#################################################################
#    Data Properties
#################################################################

fis:hasMaturityDate
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has maturity date"@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:date .

fis:hasExpirationDate
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has expiration date"@en ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:date .

fis:hasParValue
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has par value"@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal .

fis:hasCouponRate
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has coupon rate"@en ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal .

fis:hasStrikePrice
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has strike price"@en ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal .

fis:hasNotionalAmount
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has notional amount"@en ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:decimal .

fis:hasConversionPrice
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has conversion price"@en ;
    rdfs:domain fis:ConvertibleBond ;
    rdfs:range xsd:decimal .

fis:hasConversionRatio
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has conversion ratio"@en ;
    rdfs:domain fis:ConvertibleBond ;
    rdfs:range xsd:decimal .

#################################################################
#    Top-Level Classes
#################################################################

fis:LegalEntity
    a owl:Class ;
    rdfs:label "Legal Entity"@en ;
    rdfs:subClassOf owl:Thing .

fis:Corporation
    a owl:Class ;
    rdfs:label "Corporation"@en ;
    rdfs:subClassOf fis:LegalEntity .

fis:SovereignGovernment
    a owl:Class ;
    rdfs:label "Sovereign Government"@en ;
    rdfs:subClassOf fis:LegalEntity .

fis:LocalGovernment
    a owl:Class ;
    rdfs:label "Local Government"@en ;
    rdfs:subClassOf fis:LegalEntity .

fis:SupranationalOrganization
    a owl:Class ;
    rdfs:label "Supranational Organization"@en ;
    rdfs:subClassOf fis:LegalEntity .

fis:FinancialInstitution
    a owl:Class ;
    rdfs:label "Financial Institution"@en ;
    rdfs:subClassOf fis:Corporation .

fis:Bank
    a owl:Class ;
    rdfs:label "Bank"@en ;
    rdfs:subClassOf fis:FinancialInstitution .

fis:StockExchange
    a owl:Class ;
    rdfs:label "Stock Exchange"@en ;
    rdfs:subClassOf fis:LegalEntity .

#################################################################
#    Financial Instruments & Securities Hierarchy
#################################################################

fis:FinancialInstrument
    a owl:Class ;
    rdfs:label "Financial Instrument"@en ;
    rdfs:subClassOf owl:Thing ;
    rdfs:comment "A monetary contract between parties that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity."@en .

fis:Security
    a owl:Class ;
    rdfs:label "Security"@en ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "A tradable financial asset. Note conflict: US regulatory law broadly includes equities, debt, and derivatives as securities; some jurisdictions (e.g. EU/UK variations) specifically exclude non-equity/fixed-income instruments from certain strict definitions."@en .

fis:CashInstrument
    a owl:Class ;
    rdfs:label "Cash Instrument"@en ;
    rdfs:subClassOf fis:FinancialInstrument ;
    owl:disjointWith fis:Derivative ;
    rdfs:comment "Financial instrument whose value is determined directly by the markets, distinct from derivatives."@en .

fis:DebtSecurity
    a owl:Class ;
    rdfs:label "Debt Security"@en ;
    rdfs:subClassOf fis:Security, fis:CashInstrument ;
    rdfs:comment "A negotiable financial instrument serving as evidence of a promise by the issuer to pay principal and typically interest to the holder."@en .

fis:EquitySecurity
    a owl:Class ;
    rdfs:label "Equity Security"@en ;
    rdfs:subClassOf fis:Security, fis:CashInstrument ;
    rdfs:comment "A negotiable financial instrument representing an equity ownership stake in an entity and a residual claim on its assets."@en .

fis:HybridSecurity
    a owl:Class ;
    rdfs:label "Hybrid Security"@en ;
    rdfs:subClassOf fis:Security ;
    rdfs:comment "A security combining characteristics of both debt and equity securities."@en .

fis:Derivative
    a owl:Class ;
    rdfs:label "Derivative"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:FinancialInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom owl:Thing ]
        )
    ] ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "A financial contract whose value depends on the value of one or more underlying reference assets, rates, or indices."@en .

#################################################################
#    Debt Securities Hierarchy
#################################################################

fis:Bond
    a owl:Class ;
    rdfs:label "Bond"@en ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:comment "A long-term debt security under which the issuer owes the holder a debt and commits to repay principal and periodic coupon payments."@en .

fis:GovernmentBond
    a owl:Class ;
    rdfs:label "Government Bond"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
        )
    ] ;
    rdfs:subClassOf fis:Bond .

fis:TreasuryBond
    a owl:Class ;
    rdfs:label "Treasury Bond"@en ;
    rdfs:subClassOf fis:GovernmentBond .

fis:CorporateBond
    a owl:Class ;
    rdfs:label "Corporate Bond"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
        )
    ] ;
    rdfs:subClassOf fis:Bond .

fis:MunicipalBond
    a owl:Class ;
    rdfs:label "Municipal Bond"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ]
        )
    ] ;
    rdfs:subClassOf fis:Bond .

fis:GeneralObligationBond
    a owl:Class ;
    rdfs:label "General Obligation Bond"@en ;
    rdfs:subClassOf fis:MunicipalBond .

fis:RevenueBond
    a owl:Class ;
    rdfs:label "Revenue Bond"@en ;
    rdfs:subClassOf fis:MunicipalBond .

fis:SupranationalBond
    a owl:Class ;
    rdfs:label "Supranational Bond"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ]
        )
    ] ;
    rdfs:subClassOf fis:Bond .

fis:ZeroCouponBond
    a owl:Class ;
    rdfs:label "Zero Coupon Bond"@en ;
    rdfs:subClassOf fis:Bond ;
    rdfs:comment "A bond that does not make periodic interest payments and is issued at a discount, repaying par at maturity."@en .

fis:FixedRateBond
    a owl:Class ;
    rdfs:label "Fixed Rate Bond"@en ;
    rdfs:subClassOf fis:Bond .

fis:FloatingRateNote
    a owl:Class ;
    rdfs:label "Floating Rate Note"@en ;
    rdfs:subClassOf fis:Bond .

fis:InflationIndexedBond
    a owl:Class ;
    rdfs:label "Inflation Indexed Bond"@en ;
    rdfs:subClassOf fis:Bond .

fis:PerpetualBond
    a owl:Class ;
    rdfs:label "Perpetual Bond"@en ;
    rdfs:subClassOf fis:Bond ;
    rdfs:comment "A bond with no maturity date."@en .

fis:CallableBond
    a owl:Class ;
    rdfs:label "Callable Bond"@en ;
    rdfs:subClassOf fis:Bond .

fis:PutableBond
    a owl:Class ;
    rdfs:label "Putable Bond"@en ;
    rdfs:subClassOf fis:Bond .

fis:ConvertibleBond
    a owl:Class ;
    rdfs:label "Convertible Bond"@en ;
    rdfs:subClassOf fis:Bond, fis:HybridSecurity ;
    rdfs:comment "A bond that gives the holder the right to convert into a specified number of common shares."@en .

fis:AssetBackedSecurity
    a owl:Class ;
    rdfs:label "Asset-Backed Security"@en ;
    rdfs:subClassOf fis:Bond ;
    rdfs:comment "A debt security whose value and cash flows are derived from and backed by a specified pool of underlying assets."@en .

fis:MortgageBackedSecurity
    a owl:Class ;
    rdfs:label "Mortgage-Backed Security"@en ;
    rdfs:subClassOf fis:AssetBackedSecurity .

fis:ResidentialMortgageBackedSecurity
    a owl:Class ;
    rdfs:label "Residential Mortgage-Backed Security"@en ;
    rdfs:subClassOf fis:MortgageBackedSecurity .

fis:CommercialMortgageBackedSecurity
    a owl:Class ;
    rdfs:label "Commercial Mortgage-Backed Security"@en ;
    rdfs:subClassOf fis:MortgageBackedSecurity .

fis:CollateralizedMortgageObligation
    a owl:Class ;
    rdfs:label "Collateralized Mortgage Obligation"@en ;
    rdfs:subClassOf fis:MortgageBackedSecurity .

fis:CollateralizedDebtObligation
    a owl:Class ;
    rdfs:label "Collateralized Debt Obligation"@en ;
    rdfs:subClassOf fis:AssetBackedSecurity .

fis:CoveredBond
    a owl:Class ;
    rdfs:label "Covered Bond"@en ;
    rdfs:subClassOf fis:Bond .

fis:MoneyMarketInstrument
    a owl:Class ;
    rdfs:label "Money Market Instrument"@en ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:comment "Short-term debt instruments with an original maturity of one year or less."@en .

fis:CommercialPaper
    a owl:Class ;
    rdfs:label "Commercial Paper"@en ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:comment "Unsecured promissory note issued by corporations with maturity typically not more than 270 days."@en .

fis:CertificateOfDeposit
    a owl:Class ;
    rdfs:label "Certificate of Deposit"@en ;
    rdfs:subClassOf fis:MoneyMarketInstrument .

fis:TreasuryBill
    a owl:Class ;
    rdfs:label "Treasury Bill"@en ;
    rdfs:subClassOf fis:MoneyMarketInstrument, fis:ZeroCouponBond .

fis:RepurchaseAgreement
    a owl:Class ;
    rdfs:label "Repurchase Agreement"@en ;
    rdfs:subClassOf fis:MoneyMarketInstrument .

fis:Debenture
    a owl:Class ;
    rdfs:label "Debenture"@en ;
    rdfs:subClassOf fis:DebtSecurity .

fis:Note
    a owl:Class ;
    rdfs:label "Note"@en ;
    rdfs:subClassOf fis:DebtSecurity .

#################################################################
#    Equity Securities Hierarchy
#################################################################

fis:Stock
    a owl:Class ;
    rdfs:label "Stock"@en ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:comment "Shares constituting the equity capital of a corporation."@en .

fis:CommonStock
    a owl:Class ;
    rdfs:label "Common Stock"@en ;
    rdfs:subClassOf fis:Stock ;
    rdfs:comment "Corporate equity share granting voting rights and residual profit participation."@en .

fis:PreferredStock
    a owl:Class ;
    rdfs:label "Preferred Stock"@en ;
    rdfs:subClassOf fis:Stock, fis:HybridSecurity ;
    rdfs:comment "Capital stock possessing preference over common stock in dividend payments and liquidation proceeds."@en .

fis:CumulativePreferredStock
    a owl:Class ;
    rdfs:label "Cumulative Preferred Stock"@en ;
    rdfs:subClassOf fis:PreferredStock .

fis:NonCumulativePreferredStock
    a owl:Class ;
    rdfs:label "Non-Cumulative Preferred Stock"@en ;
    rdfs:subClassOf fis:PreferredStock .

fis:ConvertiblePreferredStock
    a owl:Class ;
    rdfs:label "Convertible Preferred Stock"@en ;
    rdfs:subClassOf fis:PreferredStock .

fis:DepositaryReceipt
    a owl:Class ;
    rdfs:label "Depositary Receipt"@en ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:comment "Negotiable instrument issued by a bank representing shares in a foreign corporation."@en .

fis:AmericanDepositaryReceipt
    a owl:Class ;
    rdfs:label "American Depositary Receipt"@en ;
    rdfs:subClassOf fis:DepositaryReceipt .

fis:EuropeanDepositaryReceipt
    a owl:Class ;
    rdfs:label "European Depositary Receipt"@en ;
    rdfs:subClassOf fis:DepositaryReceipt .

fis:GlobalDepositaryReceipt
    a owl:Class ;
    rdfs:label "Global Depositary Receipt"@en ;
    rdfs:subClassOf fis:DepositaryReceipt .

#################################################################
#    Investment Funds Hierarchy
#################################################################

fis:InvestmentFund
    a owl:Class ;
    rdfs:label "Investment Fund"@en ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:comment "A pooled investment vehicle that issues units or shares to investors."@en .

fis:MutualFund
    a owl:Class ;
    rdfs:label "Mutual Fund"@en ;
    rdfs:subClassOf fis:InvestmentFund .

fis:ExchangeTradedFund
    a owl:Class ;
    rdfs:label "Exchange-Traded Fund"@en ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:comment "An investment fund whose shares trade on national securities exchanges at market prices."@en .

fis:HedgeFund
    a owl:Class ;
    rdfs:label "Hedge Fund"@en ;
    rdfs:subClassOf fis:InvestmentFund .

#################################################################
#    Derivatives Hierarchy
#################################################################

fis:Forward
    a owl:Class ;
    rdfs:label "Forward"@en ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:comment "A customized, bilateral over-the-counter contract to buy or sell an underlying at a predetermined price on a future date."@en .

fis:Future
    a owl:Class ;
    rdfs:label "Future"@en ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:comment "A standardized, exchange-traded contract obligating delivery or settlement of an underlying at a specified future date and price."@en .

fis:StockFuture
    a owl:Class ;
    rdfs:label "Stock Future"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Future
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ]
        )
    ] ;
    rdfs:subClassOf fis:Future .

fis:Option
    a owl:Class ;
    rdfs:label "Option"@en ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:comment "A contract conveying the right, but not the obligation, to buy or sell an underlying at a specified strike price on or before a specified date."@en .

fis:CallOption
    a owl:Class ;
    rdfs:label "Call Option"@en ;
    rdfs:subClassOf fis:Option ;
    owl:disjointWith fis:PutOption ;
    rdfs:comment "An option contract giving the owner the right to purchase the underlying."@en .

fis:PutOption
    a owl:Class ;
    rdfs:label "Put Option"@en ;
    rdfs:subClassOf fis:Option ;
    rdfs:comment "An option contract giving the owner the right to sell the underlying."@en .

fis:AmericanOption
    a owl:Class ;
    rdfs:label "American Option"@en ;
    rdfs:subClassOf fis:Option ;
    owl:disjointWith fis:EuropeanOption ;
    rdfs:comment "An option that can be exercised on any trading day on or before expiration."@en .

fis:EuropeanOption
    a owl:Class ;
    rdfs:label "European Option"@en ;
    rdfs:subClassOf fis:Option ;
    rdfs:comment "An option that may only be exercised on the expiration date."@en .

fis:StockOption
    a owl:Class ;
    rdfs:label "Stock Option"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Option
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ]
        )
    ] ;
    rdfs:subClassOf fis:Option .

fis:Warrant
    a owl:Class ;
    rdfs:label "Warrant"@en ;
    rdfs:subClassOf fis:Option ;
    rdfs:comment "A long-dated option issued by a company to purchase shares."@en .

fis:Swap
    a owl:Class ;
    rdfs:label "Swap"@en ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:comment "A derivative contract in which counterparties exchange streams of cash flows based on an underlying reference."@en .

fis:InterestRateSwap
    a owl:Class ;
    rdfs:label "Interest Rate Swap"@en ;
    rdfs:subClassOf fis:Swap .

fis:CurrencySwap
    a owl:Class ;
    rdfs:label "Currency Swap"@en ;
    rdfs:subClassOf fis:Swap .

fis:CreditDefaultSwap
    a owl:Class ;
    rdfs:label "Credit Default Swap"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Swap
            [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:LegalEntity ]
        )
    ] ;
    rdfs:subClassOf fis:Swap ;
    rdfs:comment "A swap contract providing protection against default by a reference entity."@en .

#################################################################
#    Disjointness Axioms
#################################################################

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:DebtSecurity
        fis:EquitySecurity
        fis:Derivative
    ) .

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:Forward
        fis:Future
        fis:Option
        fis:Swap
    ) .

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:GovernmentBond
        fis:CorporateBond
        fis:MunicipalBond
        fis:SupranationalBond
    ) .

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:MutualFund
        fis:ExchangeTradedFund
        fis:HedgeFund
    ) .

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:CommonStock
        fis:PreferredStock
    ) .

[] a owl:AllDisjointClasses ;
    owl:members (
        fis:Corporation
        fis:SovereignGovernment
        fis:LocalGovernment
        fis:SupranationalOrganization
    ) .
```
